<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_post();$raw=file_get_contents('php://input')?:'';$data=json_decode($raw,true);if(!is_array($data))json_response(false,'Invalid JSON body',null,400);$provider=strtoupper(trim((string)($_SERVER['HTTP_X_PAYMENT_PROVIDER']??'')));$signature=trim((string)($_SERVER['HTTP_X_PAYMENT_SIGNATURE']??''));try{$result=process_payment_webhook($provider,trim((string)($data['event_id']??'')),trim((string)($data['payment_id']??'')),trim((string)($data['provider_payment_id']??'')),trim((string)($data['status']??'')),$raw,$signature);json_response(true,'Webhook processed',$result);}catch(InvalidArgumentException $e){json_response(false,$e->getMessage(),null,422);}catch(RuntimeException $e){log_security(null,'PAYMENT_WEBHOOK_REJECTED','HIGH',$e->getMessage(),['provider'=>$provider]);json_response(false,'Webhook rejected',null,401);}
